  "白話解釋計畫": "白话解释计划",
  "目前沒有失敗的查詢可以修正。請先在查詢分頁執行一次，/fix 才拿得到錯誤訊息與出錯的語句。": "目前没有失败的查询可以修正。请先在查询分页执行一次，/fix 才拿得到错误消息与出错的语句。",
