  "在目前連線執行這段 SQL（寫入語句會先進入審查並執行：AI 審查與備份）": "在目前连接执行这段 SQL（写入语句会先进入审查并执行：AI 审查与备份）",
  "在查詢分頁開啟": "在查询分页打开",
