  "有失敗": "有失败",
  "此連線為唯讀模式，已擋下寫入語句。": "此连接为只读模式，已挡下写入语句。",
  "此連線為唯讀模式，只能產生備份": "此连接为只读模式，只能生成备份",
  "自動產生，請勿填值": "自动生成，请勿填值",
  "你是 SQL 編輯助手，請依使用者的指示改寫下面這段 SQL。": "你是 SQL 编辑助手，请依用户的指示改写下面这段 SQL。",
  "你是測試資料產生器，請為下面這張資料表產生測試資料。": "你是测试数据生成器，请为下面这张数据表生成测试数据。",
  "你是資料庫效能調校專家，請把下面這份執行計畫解讀給使用者聽。": "你是数据库性能调校专家，请把下面这份执行计划解读给用户听。",
  "你是資料庫效能調校專家，請改寫下面這段 SQL 讓它更快。": "你是数据库性能调校专家，请改写下面这段 SQL 让它更快。",
  "你是資料庫遷移專家，請把下面這段 {from} 的 SQL 改寫成 {to} 可以執行的語句。": "你是数据库迁移专家，请把下面这段 {from} 的 SQL 改写成 {to} 可以执行的语句。",
  "你是資深資料庫工程師，下面這段 SQL 執行失敗了，請把它修好。": "你是资深数据库工程师，下面这段 SQL 执行失败了，请把它修好。",
  "你是資深資料庫工程師，請向使用者解釋下面這段 SQL。": "你是资深数据库工程师，请向用户解释下面这段 SQL。",
  "你是資深資料庫工程師，請替下面這段 SQL 加上註解。": "你是资深数据库工程师，请替下面这段 SQL 加上注解。",
