  "每句擷取上限（列）": "每句截取上限（行）",
  "沒有 AI 審查也可以繼續：備份、回滾腳本與差異報告不受影響。": "没有 AI 审查也可以继续：备份、回滚脚本与差异报告不受影响。",
  "沒有可以最佳化的 SQL。請在 /optimize 後面直接貼上語句，或先在查詢分頁裡選取一段。": "没有可以优化的 SQL。请在 /optimize 后面直接粘贴语句，或先在查询分页里选取一段。",
  "沒有可以解釋的 SQL。請在 /explain 後面直接貼上語句，或先在查詢分頁裡選取一段。": "没有可以解释的 SQL。请在 /explain 后面直接粘贴语句，或先在查询分页里选取一段。",
  "沒有可執行的語句。": "没有可执行的语句。",
  "沒有執行錯誤可修正": "没有执行错误可修正",
