  "例如：改用 CTE 改寫、加上分頁、把 JOIN 換成 EXISTS…（Enter 送出、Esc 取消）": "例如：改用 CTE 改写、加上分页、把 JOIN 换成 EXISTS…（Enter 送出、Esc 取消）",
