  "其中 {n} 句為破壞性操作（DROP / TRUNCATE / 無 WHERE 的寫入）。": "其中 {n} 句为破坏性操作（DROP / TRUNCATE / 无 WHERE 的写入）。",
  "拒絕": "拒绝",
