  "請在 /sql 後面用一句話描述你要查什麼，例如：/sql 上個月金額最高的十筆訂單。": "请在 /sql 后面用一句话描述你要查什么，例如：/sql 上个月金额最高的十笔订单。",
  "請指定資料表，例如：/schema orders 或 /schema sakila.orders。": "请指定数据表，例如：/schema orders 或 /schema sakila.orders。",
