  "   a.「規則引擎已標出的問題」：逐條回應。同意就補上實際風險與會踩到的情境；不同意就講清楚為什麼在這段 SQL 裡是安全的。": "   a.「规则引擎已标出的问题」：逐条回应。同意就补上实际风险与会踩到的情境；不同意就讲清楚为什么在这段 SQL 里是安全的。",
  "   b.「規則引擎看不出來的問題」：語意錯誤、索引用不上（欄位加工、隱式型別轉換、前綴萬用字元）、NULL 與三值邏輯、JOIN 造成的列數放大、交易與鎖的範圍、深分頁、字元集與定序不一致等。": "   b.「规则引擎看不出来的问题」：语义错误、索引用不上（字段加工、隐式类型转换、前缀通配符）、NULL 与三值逻辑、JOIN 造成的行数放大、事务与锁的范围、深分页、字符集与排序规则不一致等。",
