  "1. 瓶頸診斷：直接讀下面的執行計畫來講。指名節點（操作或表名）與它的成本、估計列數，說明它為什麼貴（全表掃描、索引選擇度差、排序或雜湊落磁碟、巢狀迴圈把列數放大等）。不要給「建議加索引」這種沒有依據的泛論。": "1. 瓶颈诊断：直接读下面的执行计划来讲。指名节点（操作或表名）与它的成本、估计行数，说明它为什么贵（全表扫描、索引选择度差、排序或哈希落磁盘、嵌套循环把行数放大等）。不要给「建议加索引」这种没有依据的泛论。",
  "1. 瓶頸類型判讀：從延遲百分位的「形狀」推論，並明講你依據哪幾個數字。p99 遠大於 p50 → 排隊、鎖競爭或連線池不足（少數請求在等資源）；整體平坦但偏高 → 單次查詢成本就高（掃描列數多、缺索引、回傳資料量大）；最大值遠離 p99 → 偶發事件（checkpoint、GC、網路重試）。": "1. 瓶颈类型判读：从延迟百分位的「形状」推论，并明讲你依据哪几个数字。p99 远大于 p50 → 排队、锁竞争或连接池不足（少数请求在等资源）；整体平坦但偏高 → 单次查询成本就高（扫描行数多、缺索引、返回数据量大）；最大值远离 p99 → 偶发事件（checkpoint、GC、网络重试）。",
  "1. 逐條點評，分成兩段：": "1. 逐条点评，分成两段：",
  "1（升冪）": "1（升幂）",
  "10,000 列": "10,000 行",
  "100 列": "100 行",
  "100,000 列": "100,000 行",
  "15 分鐘": "15 分钟",
  "2. 建議索引：完整 DDL 放進一個 ```sql 區塊。先對照【現有索引】，不要重複建已存在的組合；複合索引要說明欄位順序的理由（等值條件在前、範圍條件在後、覆蓋欄位最後）。": "2. 建议索引：完整 DDL 放进一个 ```sql 区块。先对照【现有索引】，不要重复建已存在的组合；复合索引要说明字段顺序的理由（等值条件在前、范围条件在后、覆盖字段最后）。",
  "2. 最後給一段改寫後、可直接執行的 SQL，放進單一 ```sql 區塊：保持原本語意，不要留佔位符或省略號。若沒有需要改的地方，就附上原樣並說明理由。": "2. 最后给一段改写后、可直接执行的 SQL，放进单一 ```sql 区块：保持原本语义，不要留占位符或省略号。若没有需要改的地方，就附上原样并说明理由。",
  "2. 錯誤分組的意義：逐組說明最可能的成因（連線耗盡、逾時、死鎖、語法或權限），以及這些錯誤會不會扭曲延遲統計（失敗得快的請求會把平均拉低）。": "2. 错误分组的意义：逐组说明最可能的成因（连接耗尽、超时、死锁、语法或权限），以及这些错误会不会扭曲延迟统计（失败得快的请求会把平均拉低）。",
  "②給出修正後、可直接執行的 SQL（放進 ```sql 程式碼區塊，方便我一鍵貼回編輯器）。\n\n": "②给出修正后、可直接执行的 SQL（放进 ```sql 代码区块，方便我一键贴回编辑器）。\n\n",
  "3. 下一步該量什麼：列出 2 到 4 個可執行的下一步，指名要看的指標或工具（例如伺服器端的等待事件、鎖等待、慢查詢日誌、連線數上限、單執行緒基準線），並說明各自能區分開哪兩種假設。": "3. 下一步该量什么：列出 2 到 4 个可执行的下一步，指名要看的指标或工具（例如服务器端的等待事件、锁等待、慢查询日志、连接数上限、单线程基准线），并说明各自能区分开哪两种假设。",
  "3. 改寫後的 SQL：放進另一個 ```sql 區塊，與原查詢語意等價。": "3. 改写后的 SQL：放进另一个 ```sql 区块，与原查询语义等价。",
  "30 分鐘": "30 分钟",
  "30 秒": "30 秒",
  "4. 預期效益與風險：估計掃描列數或成本的改善幅度；並說明代價——新索引在每次 INSERT / UPDATE / DELETE 的維護成本、額外佔用的磁碟空間、建立索引期間的鎖與回填時間。": "4. 预期效益与风险：估计扫描行数或成本的改善幅度；并说明代价——新索引在每次 INSERT / UPDATE / DELETE 的维护成本、额外占用的磁盘空间、创建索引期间的锁与回填时间。",
