  "選擇目標後按「比對」。結構與資料可分頁切換；差異以來源為基準（讓目標變成來源）。": "选择目标后按「比对」。结构与数据可分页切换；差异以来源为基准（让目标变成来源）。",
  "選擇目標與模式後按「比對」。差異以來源為基準：僅來源有 = 目標需新增，僅目標有 = 目標多出。": "选择目标与模式后按「比对」。差异以来源为基准：仅来源有 = 目标需新增，仅目标有 = 目标多出。",
